def ratio(values, i):
    try:
        result = 100 / values[i]
    except ArithmeticError:
        print("A", end=" ")
        result = 0
    except LookupError:
        print("L", end=" ")
        result = -1
    else:
        print("E", end=" ")
    finally:
        print("F", end=" ")
    return result


nums = [4, 0]
for i in (0, 1, 5):
    print(ratio(nums, i))

from contextlib import contextmanager


@contextmanager
def opened(name):
    print(f"open {name}")
    yield name.upper()
    print(f"close {name}")


try:
    with opened("db") as conn:
        print(conn)
        raise RuntimeError("boom")
except RuntimeError as e:
    print("error:", e)

