def bold(func):
    def wrapper(text):
        return "<b>" + func(text) + "</b>"
    return wrapper


def upper(func):
    def wrapper(text):
        return func(text).upper()
    return wrapper


@bold
@upper
def greet(text):
    return "hi " + text


print(greet("bob"), greet.__name__)

class Temperature:
    def __init__(self, celsius):
        self.celsius = celsius

    @classmethod
    def from_fahrenheit(cls, f):
        return cls((f - 32) * 5 / 9)

    @property
    def kelvin(self):
        return self.celsius + 273

    def __eq__(self, other):
        return round(self.celsius) == round(other.celsius)

    def __repr__(self):
        return f"Temperature({self.celsius:.1f})"


a = Temperature(37)
b = Temperature.from_fahrenheit(98.6)
print(a == b, b, a.kelvin)

