import enum
from typing import assert_never


class Plan(enum.Enum):
    FREE = enum.auto()
    PRO = enum.auto()
    TEAM = enum.auto()


def monthly_fee(plan):
    if plan == Plan.FREE:
        return 0
    elif plan == Plan.PRO:
        return 1200
    else:
        assert_never(plan)


print(monthly_fee(Plan.FREE))
print(monthly_fee(Plan.TEAM))

